public class DebuggerWatchesPlugin : AbstractDebuggerPlugin {

	DebuggerWatchesProvider provider;

	public DebuggerWatchesPlugin(PluginTool tool) : base(tool)
    {

		provider = new DebuggerWatchesProvider(this);
		registerServiceProvided(typeof(DebuggerWatchesService), provider);
	}

	/* @Override */
	protected void init() {
		base.init();
	}

	/* @Override */
	protected void dispose() {
		tool.removeComponentProvider(provider);
	}

	/* @Override */
	public void processEvent(PluginEvent @event) {
		base.processEvent(@event);
		if (@event is TraceActivatedPluginEvent ev) {
			provider.coordinatesActivated(ev.getActiveCoordinates());
		}
		else if (@event is TraceClosedPluginEvent ev) {
			// Activation not good enough. Need to know if "previous" was closed
			provider.traceClosed(ev.getTrace());
		}
	}

	/* @Override */
	public void writeConfigState(SaveState saveState) {
		provider.writeConfigState(saveState);
	}

	/* @Override */
	public void readConfigState(SaveState saveState) {
		provider.readConfigState(saveState);
	}
